exercises.solution:
function largest(nums) {
  let best = nums[0];
  for (let i = 1; i < nums.length; i++) {
    if (nums[i] > best) {
      best = nums[i];
    }
  }
  return best;
}

console.log(largest([3, 9, 4, 1]));
